code_template:
// This code has THREE bugs. Find and fix them.
fn buggy_code(x: Int) -> Int {
  if x = 0 {
    return 0;
  }
  let result = x / 2;
  result;  // intended to return result
}

fn main() -> Int {
  return buggy_code(10);
}

solution:
fn fixed_code(x: Int) -> Int {
  if x == 0 {
    return 0;
  }
  x / 2
}

fn main() -> Int {
  let result = fixed_code(10);
  return result;
}
